WITH RECURSIVE PartType AS (
SELECT primary_key, part_type_sign, superior ,has_child
FROM ${tableName}
WHERE primary_key = #{partTypeCode}
UNION ALL
SELECT t.primary_key, t.part_type_sign, t.superior,t.has_child
FROM ${tableName} t
INNER JOIN PartType pt ON t.superior = pt.primary_key
)
SELECT * FROM PartType

